## The Ultimate Safe Calculator

Your calculator accepts expressions like `"ADD 5 3"`, `"SAVE my_result"`, `"RECALL my_result"`, and `"CLEAR"`. It parses commands, handles every error case, and never crashes.

### The Design

A single `evaluate` function dispatches to handlers. Results are always `Result[Str, Str]` — the output string is formatted for display.

### Step 1: Split the Command

```xiom
fn evaluate(input: Str) -> Result[Str, Str] {
  if string.str_len(input) == 0 {
    return Err("Type a command. Try: ADD 5 3, SUB 10 4, MUL 3 7, DIV 8 2");
  }

  let space = 0;
  let i = 0;
  while i < string.str_len(input) {
    if string.str_slice(input, i, i + 1) == " " && space == 0 { space = i; }
    i = i + 1;
  }

  let cmd = "";
  let rest = "";
  if space == 0 {
    cmd = input;
    rest = "";
  } else {
    cmd = string.str_slice(input, 0, space);
    rest = string.str_slice(input, space + 1, string.str_len(input));
  }

  if cmd == "ADD" || cmd == "SUB" || cmd == "MUL" || cmd == "DIV" {
    return handle_arithmetic(cmd, rest);
  }
  elif cmd == "SAVE" { return handle_save(rest); }
  elif cmd == "RECALL" { return handle_recall(rest); }
  elif cmd == "CLEAR" { return Ok("Memory cleared."); }
  else { return Err("Unknown command: " + cmd); }
}
```

### Step 2: Arithmetic Handler

```xiom
fn split_two_nums(args: Str) -> Result[(Int, Int), Str] {
  let space = 0;
  let j = 0;
  while j < string.str_len(args) {
    if string.str_slice(args, j, j + 1) == " " { space = j; }
    j = j + 1;
  }
  if space == 0 { return Err("Need two numbers separated by a space"); }
  let a = string.str_to_int(string.str_slice(args, 0, space))?;
  let b = string.str_to_int(string.str_slice(args, space + 1, string.str_len(args)))?;
  return Ok((a, b));
}

fn handle_arithmetic(op: Str, args: Str) -> Result[Str, Str] {
  let (a, b) = split_two_nums(args)?;

  if op == "ADD" { return Ok(string.int_to_str(a) + " + " + string.int_to_str(b) + " = " + string.int_to_str(a + b)); }
  elif op == "SUB" { return Ok(string.int_to_str(a) + " - " + string.int_to_str(b) + " = " + string.int_to_str(a - b)); }
  elif op == "MUL" { return Ok(string.int_to_str(a) + " * " + string.int_to_str(b) + " = " + string.int_to_str(a * b)); }
  elif op == "DIV" {
    if b == 0 { return Err("Division by zero"); }
    return Ok(string.int_to_str(a) + " / " + string.int_to_str(b) + " = " + string.int_to_str(a / b));
  }
  else { return Err("Unknown operation"); }
}
```

### Step 3: Memory Functions

```xiom
var memory_name: Str = "";
var memory_value: Int = 0;

fn handle_save(args: Str) -> Result[Str, Str] {
  let space = 0;
  let j = 0;
  while j < string.str_len(args) {
    if string.str_slice(args, j, j + 1) == " " { space = j; }
    j = j + 1;
  }
  if space == 0 { return Err("Usage: SAVE <name> <value>"); }

  let name = string.str_slice(args, 0, space);
  let val_str = string.str_slice(args, space + 1, string.str_len(args));
  let val = string.str_to_int(val_str)?;

  memory_name = name;
  memory_value = val;
  return Ok("Saved '" + name + "' = " + string.int_to_str(val));
}

fn handle_recall(name: Str) -> Result[Str, Str] {
  if name != memory_name {
    return Err("No value saved as '" + name + "'");
  }
  return Ok("Recalled '" + name + "' = " + string.int_to_str(memory_value));
}
```

### Step 4: The Main Loop

```xiom
fn main() -> Int {
  let tests = ["ADD 5 3", "SUB 10 4", "MUL 7 6", "DIV 9 0", "SAVE x 42", "RECALL x", "RECALL y", "UNKNOWN"];
  let passed = 0;
  let failed = 0;
  let i = 0;

  while i < 8 {
    match evaluate(tests[i]) {
      Ok(msg) => { io.println("[OK] " + msg); passed = passed + 1; }
      Err(e) => { io.println("[ERR] " + e); failed = failed + 1; }
    }
    i = i + 1;
  }

  io.println("---");
  io.println(string.int_to_str(passed) + " passed, " + string.int_to_str(failed) + " failed");
  return 0;
}
```

