use xiom.io;

use xiom.string;
fn split_two(nums: Str) -> Result[(Int, Int), Str] {
  let sp = 0;
  let j = 0;
  while j < string.str_len(nums) {
    if string.str_slice(nums, j, j + 1) == " " { sp = j; }
    j = j + 1;
  }
  if sp == 0 { return Err("Need two numbers"); }
  let a = string.str_to_int(string.str_slice(nums, 0, sp))?;
  let b = string.str_to_int(string.str_slice(nums, sp + 1, string.str_len(nums)))?;
  return Ok((a, b));
}

var memory: Int = 0;
var has_memory: Bool = false;

fn evaluate(input: Str) -> Result[Str, Str] {
  if string.str_len(input) == 0 { return Err("Empty input"); }
  let sp = 0;
  let i = 0;
  while i < string.str_len(input) {
    if string.str_slice(input, i, i + 1) == " " && sp == 0 { sp = i; }
    i = i + 1;
  }
  let cmd = "";
  let rest = "";
  if sp == 0 { cmd = input; rest = ""; }
  else { cmd = string.str_slice(input, 0, sp); rest = string.str_slice(input, sp + 1, string.str_len(input)); }

  if cmd == "ADD" {
    let (a, b) = split_two(rest)?;
    return Ok(string.int_to_str(a + b));
  }
  elif cmd == "SUB" {
    let (a, b) = split_two(rest)?;
    return Ok(string.int_to_str(a - b));
  }
  elif cmd == "MUL" {
    let (a, b) = split_two(rest)?;
    return Ok(string.int_to_str(a * b));
  }
  elif cmd == "DIV" {
    let (a, b) = split_two(rest)?;
    if b == 0 { return Err("Division by zero"); }
    return Ok(string.int_to_str(a / b));
  }
  elif cmd == "SAVE" {
    let val = string.str_to_int(rest)?;
    memory = val;
    has_memory = true;
    return Ok("Saved " + rest);
  }
  elif cmd == "RECALL" {
    if !has_memory { return Err("No value saved"); }
    return Ok(string.int_to_str(memory));
  }
  elif cmd == "CLEAR" {
    has_memory = false;
    return Ok("Cleared");
  }
  else { return Err("Unknown command: " + cmd); }
}

fn main() -> Int {
  match evaluate("ADD 5 3") {
    Ok(r) => { io.println(r.to_str()); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
